/**
 * SMI-7030 Wave 1 Step 4: property tests for the executable-frontmatter predicate.
 *
 * The golden table is generated by
 * scripts/tests/fixtures/executable-frontmatter/generate-fixtures.mjs against an
 * isolated install of exactly gray-matter 4.0.3, so `A` is gray-matter's own
 * opener + language resolution and `eval` records whether its javascript engine
 * actually ran. Every predicate copy (core, Node edge twin, Deno edge twin) must
 * agree with `A` on every row, and must never miss a row gray-matter evaluated.
 */
import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { isGitCryptEncrypted } from './parity-utils.ts'

const __filename = fileURLToPath(import.meta.url)
const __dirname = dirname(__filename)
const REPO_ROOT = resolve(__dirname, '..', '..', '..')

const FIXTURE = resolve(
  REPO_ROOT,
  'scripts/tests/fixtures/executable-frontmatter/gray-matter-4.0.3.cases.json'
)

interface FixtureCase {
  input: string
  A: boolean
  eval: boolean
}

const table = JSON.parse(readFileSync(FIXTURE, 'utf-8')) as {
  header: { grayMatter: { version: string } }
  cases: FixtureCase[]
}

const COPIES = [
  {
    name: 'core',
    path: resolve(REPO_ROOT, 'packages/core/src/security/scanner/SecurityScanner.frontmatter.ts'),
  },
  {
    name: 'node edge',
    path: resolve(REPO_ROOT, 'scripts/indexer/_shared/security-scanner-edge.frontmatter.ts'),
  },
  {
    name: 'deno edge',
    path: resolve(REPO_ROOT, 'supabase/functions/_shared/security-scanner-edge.frontmatter.ts'),
  },
] as const

describe('SMI-7030 executable-frontmatter golden table', () => {
  it('was generated against gray-matter 4.0.3 and holds both outcomes', () => {
    expect(table.header.grayMatter.version).toBe('4.0.3')
    // Non-vacuous: a table of all-true or all-false rows would let a constant
    // predicate pass the agreement test below.
    expect(table.cases.length).toBeGreaterThanOrEqual(50)
    expect(table.cases.some((c) => c.A)).toBe(true)
    expect(table.cases.some((c) => !c.A)).toBe(true)
    expect(table.cases.some((c) => c.eval)).toBe(true)
  })

  for (const copy of COPIES) {
    it.skipIf(isGitCryptEncrypted(copy.path))(
      `${copy.name} predicate equals A on every row, and every evaluated row is flagged`,
      async () => {
        const { opensWithExecutableFrontmatter } = (await import(copy.path)) as {
          opensWithExecutableFrontmatter: (content: string) => boolean
        }
        const disagree = table.cases.filter((c) => opensWithExecutableFrontmatter(c.input) !== c.A)
        expect(disagree.map((c) => JSON.stringify(c.input))).toEqual([])
        const missedEval = table.cases.filter(
          (c) => c.eval && !opensWithExecutableFrontmatter(c.input)
        )
        expect(missedEval.map((c) => JSON.stringify(c.input))).toEqual([])
      }
    )
  }
})
